$function$;

CREATE OR REPLACE FUNCTION better_supabase.delete_incident_postmortem_action (
  action_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_action "better_supabase"."incident_postmortem_actions"%rowtype;
  v_post "better_supabase"."incident_postmortems"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
