    when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'expenses.read'), false)
