    when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'donations.read'), false)
    when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'warranty.read'), false)
    when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'dispatch.read'), false)
    when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'shipments.read'), false)
    when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'contracts.read'), false)
    when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (upsert_reminder.subject_id)::uuid and s."tenant_id" = upsert_reminder.tenant) and coalesce(better_supabase.can('tenant', upsert_reminder.tenant, 'compliance.read'), false)
