end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_template (
  template_id uuid,
  tenant      uuid,
  type        text,
  name        text,
  language    text,
  settings    jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."templates"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if upsert_template.settings is not null and jsonb_typeof(upsert_template.settings) <> 'object' then
    raise exception 'settings must be an object' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if upsert_template.template_id is not null then
    select * into v_row from "better_supabase"."templates" x where x."id" = upsert_template.template_id for update;
    if not found or v_row."tenant_id" is distinct from upsert_template.tenant then
      raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
    end if;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_template.tenant is not null and coalesce(better_supabase.can('tenant', upsert_template.tenant, 'templates.manage'), false))) then
    raise exception 'You may not change templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if upsert_template.template_id is null and (upsert_template.type is null or upsert_template.type !~ '^[a-z][a-z0-9_.-]{0,63}$') then
    raise exception 'type must be lower-case letters, digits, dots, dashes or underscores' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if upsert_template.template_id is null and upsert_template.name is null then
    raise exception 'A template needs a name' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_template_save"(uuid, text, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::jsonb)', v_hook::oid::regproc)
        using upsert_template.tenant, coalesce(upsert_template.type, v_row."type"), upsert_template.settings;
    end if;
  end;
  if upsert_template.template_id is null then
    insert into "better_supabase"."templates" ("tenant_id", "scope", "type", "name", "language", "settings", "created_by")
    values (
      upsert_template.tenant,
      case when upsert_template.tenant is null then 'system' else 'tenant' end,
      upsert_template.type,
      upsert_template.name,
      coalesce(upsert_template.language, 'en'),
      coalesce(upsert_template.settings, '{}'::jsonb),
      (select auth.uid())
    )
    returning * into v_row;
  else
    update "better_supabase"."templates" x set
      "name" = coalesce(upsert_template.name, x."name"),
      "language" = coalesce(upsert_template.language, x."language"),
      "settings" = coalesce(upsert_template.settings, x."settings"),
      "is_default" = x."is_default" and coalesce(upsert_template.language, x."language") = x."language",
      "updated_at" = now()
    where x."id" = upsert_template.template_id
    returning * into v_row;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_template_save"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object(
    'id', v_row."id",
    'tenant', v_row."tenant_id",
    'scope', v_row."scope",
    'brand', v_row."brand",
    'key', v_row."key",
    'type', v_row."type",
    'name', v_row."name",
    'language', v_row."language",
    'isDefault', v_row."is_default",
    'settings', v_row."settings",
    'forkedFrom', v_row."forked_from",
    'forkedFromVersion', v_row."forked_from_version",
    'publishedVersion', (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."id" and y."published_at" is not null order by y."version" desc limit 1),
    'upstreamVersion', case when v_row."forked_from" is not null then (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."forked_from" and y."published_at" is not null order by y."version" desc limit 1) end,
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_template_draft (
  template_id uuid,
  body        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_row "better_supabase"."template_versions"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = upsert_template_draft.template_id for update;
  if not found then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tpl."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_tpl."tenant_id", 'templates.manage'), false))) then
    raise exception 'You may not edit this template' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if upsert_template_draft.body is null then
    raise exception 'A template version needs a body' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  update "better_supabase"."template_versions" x set
    "body" = upsert_template_draft.body,
    "hash" = encode(extensions.digest(upsert_template_draft.body::text, 'sha256'), 'hex')
  where x."template_id" = upsert_template_draft.template_id and x."published_at" is null
  returning * into v_row;
  if not found then
    insert into "better_supabase"."template_versions" ("template_id", "version", "body", "hash", "created_by")
    values (
      upsert_template_draft.template_id,
      coalesce((select max(y."version") from "better_supabase"."template_versions" y where y."template_id" = upsert_template_draft.template_id), 0) + 1,
      upsert_template_draft.body,
      encode(extensions.digest(upsert_template_draft.body::text, 'sha256'), 'hex'),
      (select auth.uid())
    )
    returning * into v_row;
  end if;
  update "better_supabase"."templates" x set "updated_at" = now() where x."id" = upsert_template_draft.template_id;
  return jsonb_build_object(
    'id', v_row."id",
    'template', v_row."template_id",
    'version', v_row."version",
    'hash', v_row."hash",
    'publishedAt', v_row."published_at",
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'body', v_row."body"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_template_schedule (
  schedule_id uuid,
  template_id uuid,
  tenant      uuid,
  dtstart     timestamp with time zone,
  tzid        text,
  rrule       text,
  input       jsonb,
  enabled     boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_row "better_supabase"."template_schedules"%rowtype;
  v_rule "better_supabase"."recurrence_rules"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if upsert_template_schedule.tenant is null then
    raise exception 'A schedule needs a tenant' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_template_schedule.tenant is not null and coalesce(better_supabase.can('tenant', upsert_template_schedule.tenant, 'templates.manage'), false))) then
    raise exception 'You may not schedule templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if upsert_template_schedule.dtstart is null or coalesce(length(upsert_template_schedule.rrule), 0) not between 1 and 1000 then
    raise exception 'A schedule needs a start and a rule' using errcode = '22023', hint = 'TEMPLATE_SCHEDULE_INVALID';
  end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = coalesce(upsert_template_schedule.tzid, 'UTC')) then
    raise exception 'tzid must be an IANA time zone' using errcode = '22023', hint = 'TEMPLATE_SCHEDULE_INVALID';
  end if;
  if upsert_template_schedule.input is not null and jsonb_typeof(upsert_template_schedule.input) <> 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = upsert_template_schedule.template_id;
  if not found or not (v_tpl."scope" = 'system' or v_tpl."tenant_id" = upsert_template_schedule.tenant or (v_tpl."scope" = 'brand' and v_tpl."brand" = "better_supabase"."template_brand"(upsert_template_schedule.tenant))) then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if upsert_template_schedule.schedule_id is null then
    insert into "better_supabase"."template_schedules" ("template_id", "tenant_id", "input", "enabled", "created_by")
    values (v_tpl."id", upsert_template_schedule.tenant, coalesce(upsert_template_schedule.input, '{}'::jsonb),
      coalesce(upsert_template_schedule.enabled, true), (select auth.uid()))
    returning * into v_row;
  else
    update "better_supabase"."template_schedules" x set
      "template_id" = v_tpl."id",
      "input" = coalesce(upsert_template_schedule.input, x."input"),
      "enabled" = coalesce(upsert_template_schedule.enabled, x."enabled"),
      "updated_at" = now()
    where x."id" = upsert_template_schedule.schedule_id and x."tenant_id" = upsert_template_schedule.tenant
    returning * into v_row;
    if not found then
      raise exception 'No such schedule' using errcode = 'P0002', hint = 'TEMPLATE_SCHEDULE_NOT_FOUND';
    end if;
  end if;
  update "better_supabase"."recurrence_rules" u set
    "dtstart" = upsert_template_schedule.dtstart,
    "tzid" = coalesce(upsert_template_schedule.tzid, 'UTC'),
    "rrule" = upsert_template_schedule.rrule
  where u."tenant_id" = v_row."tenant_id"
      and u."subject_type" = 'template_schedule'
      and u."subject_id" = v_row."id"::text
  returning * into v_rule;
  if not found then
    insert into "better_supabase"."recurrence_rules" ("tenant_id", "subject_type", "subject_id", "dtstart", "tzid", "rrule")
    values (v_row."tenant_id", 'template_schedule', v_row."id"::text, upsert_template_schedule.dtstart,
      coalesce(upsert_template_schedule.tzid, 'UTC'), upsert_template_schedule.rrule)
    returning * into v_rule;
  end if;
  return jsonb_build_object(
    'id', v_row."id",
    'template', v_row."template_id",
    'tenant', v_row."tenant_id",
    'input', v_row."input",
    'enabled', v_row."enabled",
    'dtstart', v_rule."dtstart",
    'tzid', v_rule."tzid",
    'rrule', v_rule."rrule",
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_thread_summary (
  conversation uuid,
  thread       uuid,
  summary      text,
  attrs        jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_conversation uuid;
  v_tenant uuid;
  v_count integer;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'upsert_thread_summary runs as the service role' using errcode = '42501', hint = 'MESSAGING_FORBIDDEN';
  end if;
  if upsert_thread_summary.thread is null then
    select c."id", c."tenant_id" into v_conversation, v_tenant
    from "better_supabase"."conversations" c where c."id" = upsert_thread_summary.conversation;
  else
    select m."conversation_id", m."tenant_id" into v_conversation, v_tenant
    from "better_supabase"."messages" m
    where m."id" = upsert_thread_summary.thread and m."thread_id" is null and m."sent_at" is not null
      and (upsert_thread_summary.conversation is null or m."conversation_id" = upsert_thread_summary.conversation);
  end if;
  if v_conversation is null then
    raise exception 'no such conversation or thread root' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  begin
    v_count := coalesce((upsert_thread_summary.attrs ->> 'messageCount')::integer, 0);
  exception when invalid_text_representation or numeric_value_out_of_range then
    v_count := -1;
  end;
  if char_length(btrim(coalesce(upsert_thread_summary.summary, ''))) not between 1 and 20000
    or char_length(upsert_thread_summary.attrs ->> 'model') > 200
    or v_count < 0
    or upsert_thread_summary.attrs ->> 'throughAt' is null then
    raise exception 'a summary needs 1 to 20000 characters, a message count and throughAt' using errcode = '22023', hint = 'MESSAGING_SUMMARY_INVALID';
  end if;
  insert into "better_supabase"."thread_summaries" ("tenant_id", "conversation_id", "thread_id", "summary", "model", "message_count", "through_at")
  values (v_tenant, v_conversation, upsert_thread_summary.thread, btrim(upsert_thread_summary.summary),
    upsert_thread_summary.attrs ->> 'model', v_count, (upsert_thread_summary.attrs ->> 'throughAt')::timestamptz)
  on conflict ("conversation_id", "thread_id") do update
  set "summary" = excluded."summary",
    "model" = excluded."model",
    "message_count" = excluded."message_count",
    "through_at" = excluded."through_at",
    "updated_at" = now();
  return "better_supabase"."thread_summary"(v_conversation, upsert_thread_summary.thread);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_variant (
  product         uuid,
  variant         uuid,
  sku             text,
  option_values   uuid[],
  title           text,
  barcode         text,
  weight_grams    integer,
  track_inventory boolean,
  allow_backorder boolean,
  clear           text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_id uuid := upsert_variant.variant;
  v_created boolean := upsert_variant.variant is null;
  v_wanted uuid[];
  v_last text;
  v_rank text;
  v_sku text := upsert_variant.sku;
  v_defaults jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."products" x where x."id" = upsert_variant.product for update;
  if v_tenant is null then
    raise exception 'product not found' using errcode = 'P0002', hint = 'CATALOG_PRODUCT_NOT_FOUND';
  end if;
  if v_created then
    if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  else
    if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  end if;
  if exists (select 1 from unnest(coalesce(upsert_variant.clear, '{}'::text[])) c where c <> all ('{sku,title,barcode,weight}'::text[])) then
    raise exception 'clear names only sku, title, barcode, weight' using errcode = '22023', hint = 'CATALOG_CLEAR_INVALID';
  end if;
  if v_created or upsert_variant.option_values is not null then
  v_wanted := coalesce((select array_agg(distinct x order by x) from unnest(upsert_variant.option_values) x), '{}'::uuid[]);
  if cardinality(v_wanted) <> coalesce(cardinality(upsert_variant.option_values), 0)
    or exists (
      select 1 from unnest(v_wanted) x
      where not exists (
        select 1 from "better_supabase"."product_option_values" ov join "better_supabase"."product_options" o on o."id" = ov."option_id"
        where ov."id" = x and o."product_id" = upsert_variant.product
      )
    )
    or (select count(distinct ov."option_id") from "better_supabase"."product_option_values" ov where ov."id" = any (v_wanted)) <> cardinality(v_wanted)
    or (select count(*) from "better_supabase"."product_options" o where o."product_id" = upsert_variant.product) <> cardinality(v_wanted) then
    raise exception 'a variant needs exactly one value of each product option' using errcode = '22023', hint = 'CATALOG_VARIANT_OPTIONS';
  end if;
  if exists (
    select 1 from "better_supabase"."product_variants" x
    where x."product_id" = upsert_variant.product
      and x."id" is distinct from upsert_variant.variant
      and coalesce((select array_agg(y."option_value_id" order by y."option_value_id") from "better_supabase"."product_variant_values" y where y."variant_id" = x."id"), '{}'::uuid[]) = v_wanted
  ) then
    raise exception 'another variant has these option values' using errcode = '23505', hint = 'CATALOG_VARIANT_DUPLICATE';
  end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_variant_save"(uuid, uuid, text, uuid[])');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::text, $4::uuid[])', v_hook::oid::regproc)
        using upsert_variant.product, upsert_variant.variant, upsert_variant.sku, v_wanted;
    end if;
  end;
  begin
    if v_created then
      select max(x."rank" collate "C") into v_last from "better_supabase"."product_variants" x where x."product_id" = upsert_variant.product;
      v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
      execute coalesce((select 'select jsonb_build_object(' || string_agg(pg_catalog.quote_literal(a.attname) || ', ' || pg_catalog.pg_get_expr(d.adbin, d.adrelid), ', ') || ')'
    from pg_catalog.pg_attrdef d join pg_catalog.pg_attribute a on a.attrelid = d.adrelid and a.attnum = d.adnum
    where d.adrelid = '"better_supabase"."product_variants"'::regclass and a.attname = any (array[case when upsert_variant.sku is null then 'sku' end, case when upsert_variant.title is null then 'title' end, case when upsert_variant.barcode is null then 'barcode' end, case when upsert_variant.weight_grams is null then 'weight_grams' end]::text[])), 'select ''{}''::jsonb') into v_defaults;
      insert into "better_supabase"."product_variants" as x ("tenant_id", "product_id", "sku", "title", "barcode", "weight_grams", "track_inventory", "allow_backorder", "rank")
      values (v_tenant, upsert_variant.product, coalesce(upsert_variant.sku, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."sku"), coalesce(upsert_variant.title, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."title"), coalesce(upsert_variant.barcode, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."barcode"), coalesce(upsert_variant.weight_grams, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."weight_grams"), coalesce(upsert_variant.track_inventory, true), coalesce(upsert_variant.allow_backorder, false), v_rank)
      returning x."id", x."sku" into v_id, v_sku;
    else
      update "better_supabase"."product_variants" x set "sku" = case when 'sku' = any (coalesce(upsert_variant.clear, '{}'::text[])) then null else coalesce(upsert_variant.sku, x."sku") end, "title" = case when 'title' = any (coalesce(upsert_variant.clear, '{}'::text[])) then null else coalesce(upsert_variant.title, x."title") end, "barcode" = case when 'barcode' = any (coalesce(upsert_variant.clear, '{}'::text[])) then null else coalesce(upsert_variant.barcode, x."barcode") end, "weight_grams" = case when 'weight' = any (coalesce(upsert_variant.clear, '{}'::text[])) then null else coalesce(upsert_variant.weight_grams, x."weight_grams") end, "track_inventory" = coalesce(upsert_variant.track_inventory, x."track_inventory"), "allow_backorder" = coalesce(upsert_variant.allow_backorder, x."allow_backorder"), "updated_at" = now()
      where x."id" = upsert_variant.variant and x."product_id" = upsert_variant.product
      returning x."rank", x."sku" into v_rank, v_sku;
      if not found then
        raise exception 'variant not found' using errcode = 'P0002', hint = 'CATALOG_VARIANT_NOT_FOUND';
      end if;
    end if;
  exception when unique_violation then
    declare
      v_constraint text;
    begin
      get stacked diagnostics v_constraint = constraint_name;
      if exists (
        select 1 from pg_catalog.pg_index i
        join pg_catalog.pg_class c on c.oid = i.indexrelid
        where i.indrelid = '"better_supabase"."product_variants"'::regclass and c.relname = v_constraint
          and (exists (select 1 from pg_catalog.pg_attribute a where a.attrelid = i.indrelid and a.attnum = any (i.indkey) and a.attname = 'sku')
            or coalesce(pg_catalog.pg_get_expr(i.indexprs, i.indrelid), '') ~ ('\m' || 'sku' || '\M'))
      ) then
        raise exception 'another variant has this SKU' using errcode = '23505', hint = 'CATALOG_SKU_TAKEN';
      end if;
      raise;
    end;
  end;
  if v_wanted is not null then
  delete from "better_supabase"."product_variant_values" x where x."variant_id" = v_id and not (x."option_value_id" = any (v_wanted));
  insert into "better_supabase"."product_variant_values" ("tenant_id", "variant_id", "option_value_id")
  select v_tenant, v_id, x from unnest(v_wanted) x
  on conflict do nothing;
  end if;
  if v_created then
    perform "better_supabase".emit_event('product_variant.created', jsonb_build_object('organizationId', v_tenant, 'id', v_id, 'productId', upsert_variant.product, 'sku', v_sku), 'variants/' || v_id::text, (v_tenant)::text, null, 'better-supabase/catalog');
  else
    perform "better_supabase".emit_event('product_variant.updated', jsonb_build_object('organizationId', v_tenant, 'id', v_id, 'productId', upsert_variant.product, 'sku', v_sku), 'variants/' || v_id::text, (v_tenant)::text, null, 'better-supabase/catalog');
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_variant_save"(uuid, boolean)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::boolean)', v_hook::oid::regproc)
        using v_id, v_created;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'sku', v_sku, 'rank', v_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_variant_size (
  tenant uuid,
  input  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_variant uuid;
  v_size numeric;
  v_row "better_supabase"."variant_sizes";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_variant_size.tenant is not null and coalesce(better_supabase.can('tenant', upsert_variant_size.tenant, 'warehouse.manage'), false))) then
    raise exception 'not allowed to manage variant sizes' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if jsonb_typeof(upsert_variant_size.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  begin
    v_variant := (upsert_variant_size.input ->> 'variantId')::uuid;
    v_size := (upsert_variant_size.input ->> 'size')::numeric;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'variantId is a uuid and size a number' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end;
  if v_size is null or v_size <= 0 then
    raise exception 'size is more than 0' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" x where x."id" = v_variant and x."tenant_id" = upsert_variant_size.tenant) then
    raise exception 'no such variant in this organization' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  insert into "better_supabase"."variant_sizes" ("tenant_id", "variant_id", "size")
  values (upsert_variant_size.tenant, v_variant, v_size)
  on conflict ("variant_id") do update set "size" = excluded."size", "updated_at" = now()
  returning * into v_row;
  return jsonb_build_object('variantId', v_row."variant_id", 'size', v_row."size"::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_vex_statement (
  tenant           uuid,
  product_id       uuid,
  vulnerability_id uuid,
  status           text,
  version_id       uuid DEFAULT NULL::uuid,
  justification    text DEFAULT NULL::text,
  impact_statement text DEFAULT NULL::text,
  action_statement text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."vex_statements";
  v_old "better_supabase"."vex_statements";
  v_vuln text;
  v_label text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_vex_statement.tenant is not null and coalesce(better_supabase.can('tenant', upsert_vex_statement.tenant, 'advisories.write'), false))) then
    raise exception 'not allowed to change advisories' using errcode = '42501', hint = 'ADVISORY_FORBIDDEN';
  end if;
  if coalesce(upsert_vex_statement.status, '') not in ('not_affected', 'affected', 'fixed', 'under_investigation') then
    raise exception 'status must be one of not_affected, affected, fixed, under_investigation' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if upsert_vex_statement.status = 'not_affected' and (upsert_vex_statement.justification is null and nullif(trim(upsert_vex_statement.impact_statement), '') is null) then
    raise exception 'not_affected needs a justification or an impact statement' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if upsert_vex_statement.justification is not null and (upsert_vex_statement.status <> 'not_affected' or upsert_vex_statement.justification not in ('component_not_present', 'vulnerable_code_not_present', 'vulnerable_code_not_in_execute_path', 'vulnerable_code_cannot_be_controlled_by_adversary', 'inline_mitigations_already_exist')) then
    raise exception 'a justification applies to not_affected and is one of the OpenVEX justifications' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if length(upsert_vex_statement.impact_statement) > 5000 or length(upsert_vex_statement.action_statement) > 5000 then
    raise exception 'impact_statement and action_statement are at most 5000 characters' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if not exists (
    select 1 from "better_supabase"."advisory_products" y
    where y."id" = upsert_vex_statement.product_id and y."tenant_id" = upsert_vex_statement.tenant
  ) then
    raise exception 'no such product in this organization' using errcode = 'P0002', hint = 'ADVISORY_NOT_FOUND';
  end if;
  select y."vuln_id" into v_vuln from "better_supabase"."vulnerabilities" y
  where y."id" = upsert_vex_statement.vulnerability_id and y."tenant_id" = upsert_vex_statement.tenant;
  if not found then
    raise exception 'no such vulnerability in this organization' using errcode = 'P0002', hint = 'ADVISORY_NOT_FOUND';
  end if;
  if upsert_vex_statement.version_id is not null and not exists (
    select 1 from "better_supabase"."advisory_product_versions" y
    where y."id" = upsert_vex_statement.version_id and y."tenant_id" = upsert_vex_statement.tenant
      and y."product_id" = upsert_vex_statement.product_id
  ) then
    raise exception 'no such version of this product in this organization' using errcode = 'P0002', hint = 'ADVISORY_NOT_FOUND';
  end if;
  select * into v_old from "better_supabase"."vex_statements" w
  where w."tenant_id" = upsert_vex_statement.tenant and w."product_id" = upsert_vex_statement.product_id
    and w."vulnerability_id" = upsert_vex_statement.vulnerability_id
    and w."version_id" is not distinct from upsert_vex_statement.version_id
  for update;
  if v_old."id" is null then
    insert into "better_supabase"."vex_statements" ("tenant_id", "product_id", "version_id", "vulnerability_id", "status", "justification", "impact_statement", "action_statement", "created_by")
    values (upsert_vex_statement.tenant, upsert_vex_statement.product_id, upsert_vex_statement.version_id, upsert_vex_statement.vulnerability_id, upsert_vex_statement.status,
      upsert_vex_statement.justification, nullif(trim(upsert_vex_statement.impact_statement), ''), nullif(trim(upsert_vex_statement.action_statement), ''), (select auth.uid()))
    returning * into v_row;
  else
    update "better_supabase"."vex_statements" w set
      "status" = upsert_vex_statement.status,
      "justification" = upsert_vex_statement.justification,
      "impact_statement" = nullif(trim(upsert_vex_statement.impact_statement), ''),
      "action_statement" = nullif(trim(upsert_vex_statement.action_statement), ''),
      "updated_at" = now()
    where w."id" = v_old."id"
    returning * into v_row;
  end if;
  perform "better_supabase".emit_event('vex_statement.updated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'productId', v_row."product_id", 'versionId', v_row."version_id", 'vulnerabilityId', v_row."vulnerability_id", 'vulnId', v_vuln, 'status', v_row."status"), 'vex-statements/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/advisories');
  perform better_supabase.audit_event(
    event_type => 'vex_statement.updated',
    category => 'data',
    target_type => 'vex_statement',
    record_id => v_row."id"::text,
    target_label => v_vuln,
    summary => 'VEX statement saved',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'productId', v_row."product_id", 'versionId', v_row."version_id", 'vulnerabilityId', v_row."vulnerability_id", 'vulnId', v_vuln, 'status', v_row."status")
  );
  select y."version" into v_label from "better_supabase"."advisory_product_versions" y where y."id" = v_row."version_id";
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'productId', v_row."product_id", 'versionId', v_row."version_id", 'version', v_label, 'vulnerabilityId', v_row."vulnerability_id", 'vulnId', v_vuln, 'status', v_row."status", 'justification', v_row."justification", 'impactStatement', v_row."impact_statement", 'actionStatement', v_row."action_statement", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_view (
  tenant  uuid,
  list    text,
  name    text,
  kind    text,
  scope   text,
  team    text,
  state   jsonb,
  view_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid := upsert_view.view_id;
  v_inserted boolean := upsert_view.view_id is null;
  v_row "better_supabase"."shared_views";
  v_last text;
  v_rank text;
  v_service boolean := auth.role() = 'service_role';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if upsert_view.scope is null or upsert_view.scope not in ('user', 'team', 'tenant') then
    raise exception 'scope must be user, team or tenant' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if upsert_view.kind is null or upsert_view.kind not in ('table', 'board', 'calendar', 'timeline', 'gantt') then
    raise exception 'unknown view kind' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if upsert_view.state is null or jsonb_typeof(upsert_view.state) <> 'object' then
    raise exception 'state must be an object' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if not (v_service or coalesce(better_supabase.can('tenant', upsert_view.tenant, 'saved_views.read'), false)) then
    raise exception 'not allowed to save views' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
  end if;
  if upsert_view.state ? 'collectionId' and (
    jsonb_typeof(upsert_view.state -> 'collectionId') <> 'string'
    or (upsert_view.state ->> 'collectionId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or not exists (
      select 1 from "better_supabase"."subject_collections" c
      where c."id" = (upsert_view.state ->> 'collectionId')::uuid
        and c."tenant_id" = upsert_view.tenant
        and (v_service or c."scope" <> 'user' or c."owner_id" = auth.uid())
    )) then
    raise exception 'the view''s collection is not found' using errcode = 'P0002', hint = 'SAVED_VIEW_COLLECTION_NOT_FOUND';
  end if;
  if upsert_view.scope = 'user' and auth.uid() is null then
    raise exception 'a personal view needs a signed-in user' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if upsert_view.scope <> 'user' and not (v_service or coalesce(better_supabase.can('tenant', upsert_view.tenant, 'saved_views.share'), false)) then
    raise exception 'not allowed to share views' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
  end if;
  if upsert_view.scope = 'team' then
    if upsert_view.team is null then
      raise exception 'a team view needs a team' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
    end if;
    if not (v_service or upsert_view.team in (select t::text from "better_supabase"."team_ids_of"((select auth.uid())) t)) then
      raise exception 'not a member of this team' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
    end if;
  end if;
  if v_id is not null then
    select * into v_row from "better_supabase"."shared_views" where "id" = v_id and "tenant_id" = upsert_view.tenant for update;
    if not found then
      raise exception 'saved view not found' using errcode = 'P0002', hint = 'SAVED_VIEW_NOT_FOUND';
    end if;
    if not (auth.role() = 'service_role'
    or (v_row."scope" = 'user' and coalesce(v_row."owner_id" = auth.uid(), false))
    or (v_row."scope" <> 'user' and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'saved_views.share'), false))) then
      raise exception 'not allowed to change this view' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
    end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_view_save"(uuid, text, text, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text, $4::jsonb)', v_hook::oid::regproc)
        using upsert_view.tenant, upsert_view.list, upsert_view.scope, upsert_view.state;
    end if;
  end;
  if v_id is null then
    select max(v."rank" collate "C") into v_last from "better_supabase"."shared_views" v
      where v."tenant_id" = upsert_view.tenant and v."list" = upsert_view.list;
    v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
    insert into "better_supabase"."shared_views" ("tenant_id", "list", "scope", "owner_id", "team_id", "name", "kind", "state", "rank")
    values (upsert_view.tenant, upsert_view.list, upsert_view.scope, auth.uid(),
      case when upsert_view.scope = 'team' then upsert_view.team end,
      upsert_view.name, upsert_view.kind, upsert_view.state, v_rank)
    returning "id" into v_id;
  else
    update "better_supabase"."shared_views" set
      "list" = upsert_view.list,
      "scope" = upsert_view.scope,
      "team_id" = case when upsert_view.scope = 'team' then upsert_view.team end,
      "owner_id" = coalesce("owner_id", auth.uid()),
      "name" = upsert_view.name,
      "kind" = upsert_view.kind,
      "state" = upsert_view.state,
      -- The default is per list, scope and team; moving the view drops it.
      "is_default" = case
        when "scope" = upsert_view.scope and "list" = upsert_view.list
          and "team_id" is not distinct from case when upsert_view.scope = 'team' then upsert_view.team end
        then "is_default" else false end,
      "updated_at" = now()
    where "id" = v_id
    returning "rank" into v_rank;
  end if;
  if v_inserted then
    perform "better_supabase".emit_event('saved_view.created', jsonb_build_object('organizationId', upsert_view.tenant, 'id', v_id, 'kind', upsert_view.kind, 'name', upsert_view.name), 'saved-views/' || v_id::text, (upsert_view.tenant)::text, null, 'better-supabase/saved-views');
  else
    perform "better_supabase".emit_event('saved_view.updated', jsonb_build_object('organizationId', upsert_view.tenant, 'id', v_id, 'kind', upsert_view.kind, 'name', upsert_view.name), 'saved-views/' || v_id::text, (upsert_view.tenant)::text, null, 'better-supabase/saved-views');
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_view_save"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'rank', v_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_vulnerability (
  tenant         uuid,
  vuln_id        text,
  summary        text    DEFAULT NULL::text,
  details        text    DEFAULT NULL::text,
  aliases        text[]  DEFAULT NULL::text[],
  cvss_vector    text    DEFAULT NULL::text,
  cvss_version   text    DEFAULT NULL::text,
  cvss_score     numeric DEFAULT NULL::numeric,
  affected_purls text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."vulnerabilities";
  v_old "better_supabase"."vulnerabilities";
  v_id text := case when upper(trim(upsert_vulnerability.vuln_id)) like 'CVE-%' then upper(trim(upsert_vulnerability.vuln_id)) else trim(upsert_vulnerability.vuln_id) end;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_vulnerability.tenant is not null and coalesce(better_supabase.can('tenant', upsert_vulnerability.tenant, 'advisories.write'), false))) then
    raise exception 'not allowed to change advisories' using errcode = '42501', hint = 'ADVISORY_FORBIDDEN';
  end if;
  if coalesce(v_id, '') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$' then
    raise exception 'vuln_id must be a CVE, GHSA or other vulnerability id of 3 to 128 characters' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if length(upsert_vulnerability.summary) > 1000 or length(upsert_vulnerability.details) > 20000 or length(upsert_vulnerability.cvss_vector) > 300 then
    raise exception 'summary is at most 1000 characters, details 20000 and the CVSS vector 300' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if upsert_vulnerability.cvss_version is not null and upsert_vulnerability.cvss_version not in ('3.0', '3.1', '4.0') then
    raise exception 'cvss_version must be 3.0, 3.1 or 4.0' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  if upsert_vulnerability.cvss_score is not null and upsert_vulnerability.cvss_score not between 0 and 10 then
    raise exception 'cvss_score must be between 0 and 10' using errcode = '22023', hint = 'ADVISORY_INVALID';
  end if;
  select * into v_old from "better_supabase"."vulnerabilities" y
  where y."tenant_id" = upsert_vulnerability.tenant and y."vuln_id" = v_id
  for update;
  if v_old."id" is null then
    insert into "better_supabase"."vulnerabilities" ("tenant_id", "vuln_id", "summary", "details", "aliases", "cvss_vector", "cvss_version", "cvss_score", "severity", "affected_purls")
    values (upsert_vulnerability.tenant, v_id, nullif(trim(upsert_vulnerability.summary), ''), nullif(trim(upsert_vulnerability.details), ''),
      coalesce(upsert_vulnerability.aliases, '{}'::text[]), upsert_vulnerability.cvss_vector, upsert_vulnerability.cvss_version, upsert_vulnerability.cvss_score,
      (case when upsert_vulnerability.cvss_score is null then null when upsert_vulnerability.cvss_score = 0 then 'none' when upsert_vulnerability.cvss_score < 4 then 'low' when upsert_vulnerability.cvss_score < 7 then 'medium' when upsert_vulnerability.cvss_score < 9 then 'high' else 'critical' end), coalesce(upsert_vulnerability.affected_purls, '{}'::text[]))
    returning * into v_row;
    perform "better_supabase".emit_event('vulnerability.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'vulnId', v_row."vuln_id", 'severity', v_row."severity", 'cvssScore', v_row."cvss_score", 'epssScore', v_row."epss_score", 'kev', v_row."kev"), 'vulnerabilities/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/advisories');
  perform better_supabase.audit_event(
    event_type => 'vulnerability.created',
    category => 'data',
    target_type => 'vulnerability',
    record_id => v_row."id"::text,
    target_label => v_row."vuln_id",
    summary => 'vulnerability registered',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'vulnId', v_row."vuln_id", 'severity', v_row."severity", 'cvssScore', v_row."cvss_score", 'epssScore', v_row."epss_score", 'kev', v_row."kev")
  );
  else
    update "better_supabase"."vulnerabilities" y set
      "summary" = coalesce(nullif(trim(upsert_vulnerability.summary), ''), y."summary"),
      "details" = coalesce(nullif(trim(upsert_vulnerability.details), ''), y."details"),
      "aliases" = coalesce(upsert_vulnerability.aliases, y."aliases"),
      "cvss_vector" = coalesce(upsert_vulnerability.cvss_vector, y."cvss_vector"),
      "cvss_version" = coalesce(upsert_vulnerability.cvss_version, y."cvss_version"),
      "cvss_score" = coalesce(upsert_vulnerability.cvss_score, y."cvss_score"),
      "severity" = coalesce((case when upsert_vulnerability.cvss_score is null then null when upsert_vulnerability.cvss_score = 0 then 'none' when upsert_vulnerability.cvss_score < 4 then 'low' when upsert_vulnerability.cvss_score < 7 then 'medium' when upsert_vulnerability.cvss_score < 9 then 'high' else 'critical' end), y."severity"),
      "affected_purls" = coalesce(upsert_vulnerability.affected_purls, y."affected_purls"),
      "updated_at" = now()
    where y."id" = v_old."id"
    returning * into v_row;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'vulnId', v_row."vuln_id", 'aliases', to_jsonb(v_row."aliases"), 'summary', v_row."summary", 'details', v_row."details", 'cvssVector', v_row."cvss_vector", 'cvssVersion', v_row."cvss_version", 'cvssScore', v_row."cvss_score", 'severity', v_row."severity", 'epssScore', v_row."epss_score", 'epssPercentile', v_row."epss_percentile", 'epssDate', v_row."epss_date", 'kev', v_row."kev", 'kevAddedOn', v_row."kev_added_on", 'kevDueOn', v_row."kev_due_on", 'kevRansomware', v_row."kev_ransomware", 'affectedPurls', to_jsonb(v_row."affected_purls"), 'references', v_row."reference_links", 'publishedAt', v_row."published_at", 'modifiedAt', v_row."modified_at", 'enrichedAt', v_row."enriched_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_work_center (
  tenant         uuid,
  input          jsonb,
  work_center_id uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."work_centers";
  v_asset uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (upsert_work_center.tenant is not null and coalesce(better_supabase.can('tenant', upsert_work_center.tenant, 'manufacturing.manage'), false))) then
    raise exception 'not allowed to change work centers' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if jsonb_typeof(upsert_work_center.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
  if upsert_work_center.work_center_id is not null then
    select * into v_row from "better_supabase"."work_centers" x
    where x."id" = upsert_work_center.work_center_id and x."tenant_id" = upsert_work_center.tenant for update;
    if not found then
      raise exception 'no such work center in this organization' using errcode = 'P0002', hint = 'WORK_CENTER_NOT_FOUND';
    end if;
  end if;
  v_asset := case when upsert_work_center.input ? 'assetId' then nullif(upsert_work_center.input ->> 'assetId', '')::uuid else v_row."asset_id" end;
  if v_asset is not null and not exists (select 1 from "better_supabase"."assets" a where a."id" = v_asset and a."tenant_id" = upsert_work_center.tenant) then
    raise exception 'the asset isn''t an asset of this organization' using errcode = '22023', hint = 'MANUFACTURING_BOM_INVALID';
  end if;
  if upsert_work_center.work_center_id is null then
    insert into "better_supabase"."work_centers" ("tenant_id", "name", "asset_id", "hours_per_day", "cost_rate", "currency")
    values (upsert_work_center.tenant, trim(upsert_work_center.input ->> 'name'), v_asset,
      coalesce(nullif(upsert_work_center.input ->> 'hoursPerDay', '')::numeric, 8),
      coalesce(nullif(upsert_work_center.input ->> 'costRate', '')::bigint, 0),
      upper(nullif(upsert_work_center.input ->> 'currency', '')))
    returning * into v_row;
  else
    update "better_supabase"."work_centers" x set
      "name" = case when upsert_work_center.input ? 'name' then trim(upsert_work_center.input ->> 'name') else x."name" end,
      "asset_id" = v_asset,
      "hours_per_day" = coalesce(nullif(upsert_work_center.input ->> 'hoursPerDay', '')::numeric, x."hours_per_day"),
      "cost_rate" = coalesce(nullif(upsert_work_center.input ->> 'costRate', '')::bigint, x."cost_rate"),
      "currency" = case when upsert_work_center.input ? 'currency' then upper(nullif(upsert_work_center.input ->> 'currency', '')) else x."currency" end,
      "archived_at" = case when not upsert_work_center.input ? 'archived' then x."archived_at"
        when (upsert_work_center.input ->> 'archived')::boolean then coalesce(x."archived_at", now()) else null end,
      "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'name', v_row."name", 'assetId', v_row."asset_id", 'hoursPerDay', v_row."hours_per_day"::text, 'costRate', v_row."cost_rate"::text, 'currency', v_row."currency", 'archivedAt', v_row."archived_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_work_item_checklist_item (
  task           uuid,
  checklist_item uuid,
  attrs          jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."work_items";
  v_id uuid := upsert_work_item_checklist_item.checklist_item;
  v_last text;
  v_done boolean := (upsert_work_item_checklist_item.attrs ->> 'done')::boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."work_items" x where x."id" = upsert_work_item_checklist_item.task and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.write'), false)) and x."archived_at" is null;
  if v_row."id" is null then
    raise exception 'no such work item you can edit' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  begin
    if v_id is null then
      select max(y."rank") into v_last from "better_supabase"."work_item_checklist_items" y where y."work_item_id" = v_row."id";
      insert into "better_supabase"."work_item_checklist_items" ("tenant_id", "work_item_id", "title", "done", "done_at", "done_by", "rank", "created_by")
      values (v_row."tenant_id", v_row."id", trim(upsert_work_item_checklist_item.attrs ->> 'title'), coalesce(v_done, false),
        case when v_done then now() end, case when v_done then auth.uid() end,
        coalesce(upsert_work_item_checklist_item.attrs ->> 'rank', case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end), auth.uid())
      returning "id" into v_id;
    else
      update "better_supabase"."work_item_checklist_items" y set
        "title" = coalesce(trim(upsert_work_item_checklist_item.attrs ->> 'title'), y."title"),
        "rank" = coalesce(upsert_work_item_checklist_item.attrs ->> 'rank', y."rank"),
        "done" = coalesce(v_done, y."done"),
        "done_at" = case when v_done is null then y."done_at" when v_done then coalesce(y."done_at", now()) end,
        "done_by" = case when v_done is null then y."done_by" when v_done then coalesce(y."done_by", auth.uid()) end
      where y."id" = v_id and y."work_item_id" = v_row."id";
      if not found then
        raise exception 'no such checklist item on this work item' using errcode = 'P0002', hint = 'TASK_CHECKLIST_ITEM_NOT_FOUND';
      end if;
    end if;
  exception when check_violation or not_null_violation or invalid_text_representation then
    raise exception 'a checklist item needs a title of 1 to 500 characters and a valid rank' using errcode = '22023', hint = 'TASK_CHECKLIST_ITEM_INVALID';
  end;
  perform "better_supabase".emit_event('work_item.updated', jsonb_build_object('organizationId', v_row."tenant_id", 'workItemId', v_row."id", 'subjectType', 'work_item', 'subjectId', v_row."id"::text, 'title', v_row."title", 'fields', jsonb_build_array('checklist'), 'actorId', auth.uid(), 'actorKind', "better_supabase"."work_item_actor"(null) ->> 'kind', 'actorName', "better_supabase"."work_item_actor"(null) ->> 'name'), 'work_items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/tasks');
  return (select jsonb_build_object('id', y."id", 'workItemId', y."work_item_id", 'title', y."title", 'done', y."done", 'doneAt', y."done_at", 'doneBy', y."done_by", 'rank', y."rank", 'createdAt', y."created_at") from "better_supabase"."work_item_checklist_items" y where y."id" = v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.upsert_work_item_material_line (
  task    uuid,
  line_id uuid,
  attrs   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."work_items";
  v_id uuid := upsert_work_item_material_line.line_id;
  v_last text;
  v_line "better_supabase"."work_item_material_lines";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if jsonb_typeof(upsert_work_item_material_line.attrs) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'TASK_LINE_INVALID';
  end if;
  select * into v_row from "better_supabase"."work_items" x
  where x."id" = upsert_work_item_material_line.task and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.write'), false)) and x."archived_at" is null;
  if v_row."id" is null then
    raise exception 'work item not found' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  if v_id is null then
    select max(y."rank") into v_last from "better_supabase"."work_item_material_lines" y where y."work_item_id" = v_row."id";
    insert into "better_supabase"."work_item_material_lines" ("tenant_id", "work_item_id", "variant_id", "quantity", "unit", "rank")
    values (v_row."tenant_id", v_row."id", nullif(upsert_work_item_material_line.attrs ->> 'variantId', '')::uuid, nullif(upsert_work_item_material_line.attrs ->> 'quantity', '')::numeric, nullif(btrim(upsert_work_item_material_line.attrs ->> 'unit'), ''), coalesce(nullif(upsert_work_item_material_line.attrs ->> 'rank', ''), case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end))
    returning * into v_line;
  else
    update "better_supabase"."work_item_material_lines" y set "variant_id" = coalesce(nullif(upsert_work_item_material_line.attrs ->> 'variantId', '')::uuid, "variant_id"), "quantity" = coalesce(nullif(upsert_work_item_material_line.attrs ->> 'quantity', '')::numeric, "quantity"), "unit" = case when upsert_work_item_material_line.attrs ? 'unit' then nullif(btrim(upsert_work_item_material_line.attrs ->> 'unit'), '') else "unit" end, "rank" = coalesce(nullif(upsert_work_item_material_line.attrs ->> 'rank', ''), "rank")
    where y."id" = v_id and y."work_item_id" = v_row."id"
    returning * into v_line;
    if v_line."id" is null then
      raise exception 'no such line on this work item' using errcode = '22023', hint = 'TASK_LINE_INVALID';
    end if;
  end if;
  return jsonb_build_object('id', v_line."id", 'taskId', v_line."work_item_id", 'rank', v_line."rank");
end;
$function$;

